// ============================================
// ENCONTROS DE APRENDIZADO: banco de perguntas (etapa 5d-1; redação final na 5d-3)
// ---------------------------------------------
// q(id, nó, nível, formato, correta, pt, en, fatos, status)
//   formato 'mf' = Mito x Fato: `correta` é 'mito' ou 'fato' e o enunciado é uma afirmação;
//   formato 'mc' = alternativas: `correta` é o índice (0, 1 ou 2) na ordem escrita aqui (o jogo embaralha).
//   pt/en = [enunciado, [alternativas] (só mc), explicação]
//   fatos = IDs do banco docs/referencias-5c/busca/ (ou F3E-xxx = docs/fatos-historicos-3e.md)
//   status: V = fato em fonte oficial lida; V+C = com cálculo do projeto; V+R = com raciocínio do projeto
// ============================================
const q = (id, no, nivel, formato, correta, pt, en, fatos, status = 'V') => {
    const f = (a) => (formato === 'mf' ? { enunciado: a[0], explicacao: a[1] } : { enunciado: a[0], opcoes: a[1], explicacao: a[2] });
    return { id, no, nivel, formato, correta, fatos, status, pt: f(pt), en: f(en) };
};

